import runpy,json
from pathlib import Path
S=Path(__file__).resolve().parents[1];e=runpy.run_path(str(S/'work/write_superchina_small.py'));add=e['add'];out=e['out'];common=e['common'];cost=e['cost'];a26=out['SuperChina/StgBD26'];n25=a26['parameterNotes'].copy();n25.update({'價格基準':'固定格線原點，配價格間隔形成原點+k×間隔；首輪須前後報價跨格才建立策略。','價格間隔':'固定格距；一格推進子策略與加碼，距現行基準達兩格以上先按跳空全部退出。','進場調整點':'空手多用目標多−調整點；空側實作也比較目標多+調整點，並非目標空，需留意原碼不對稱。'})
add('BD25','跨固定價格格線後建立順勢加碼策略，反向一格退出並換方向；兩格跳空先整組平倉。','格線與加碼',['價格基準+k×間隔形成固定格。首筆記錄上一價，後筆跨格才建空手線；若上一價剛好在格上，下一筆直接視為跨格。','只在跨格時執行子策略，空手上觸目標多−調整點多一口；空側原碼是open<=目標多+調整點而非目標空。首次進場後基準及雙目標依方向各移一格。','有利再一格且未達次數則新增1+k×加碼口數；滿次數只再推一格保護。反向退出設新方向狀態，可同根建立反向子項並立即測進場。'],['現行基準向外距離達兩格以上先全部平倉，從目前價重新等待下一次跨格；一格反向則停止該持倉。','啟用當沖到時全部平倉並封鎖當日後續較晚時刻；換倉覆寫成舊月平倉，不重開新月。'],[common,cost,'策略基準按固定格距移動，與BD26每次重設當筆價格不同。沒有每根重算連續價格停損，也沒有資料末端強平。'],['空側進場目標疑似不對稱，但此頁按實碼說明；不能把它解讀成標準上下格完全對稱。','加碼量為新增1+k×加碼口數，累積持倉會超過固定加碼量的直覺；單日最大損失欄位尚未實作。','價格間隔為0會除以0，跨午夜封鎖靠TimeOfDay比較，不使用商品TradeDate。'],n25)
add('BD29','每日指定分鐘重設上下突破基準；持倉可跨日留存，碰反向目標或固定停損先平掉，再於次數內重進。','每日突破',['只處理Current近月，HHmm恰等於BD線開盤時間且TimeOfDay回退才畫線／重設第一個啟動子項；缺該分鐘不補。','空手且session!=1，在目標多−進場調整點以上買一口，或目標空+進場調整點以下空一口；跳空時連基準一起平移，並增加當日已進次數。'],['持多open<=固定停損價或目標空，持空open>=固定停損價或目標多，於當筆open退出；同根回到空手後可再觸發另一方向。','新日只重設基準、雙目標與已進次數，不先平倉，也不清原停損價；沒有直接停利、移停或固定日末平倉。'],[common,cost,'每日重設基準按當日open×多／空百分比換算，價位按商品最小單位Round。進場有調整點時，調後多目標=實際open+調整點、空目標=實際open−調整點。'],['主迴圈未檢查啟動欄位才分派，且硬限Current：共用換倉完成後改送Next會被忽略，不能假設換月後持續運作。','共用時間外session=1只擋新入場，舊倉停損仍可執行；按舊停損與新日雙目標孰先觸發退出，並非每天重新設一套完整風控。'],{'多進場比':'當日基準×此值/100為向上距離，decimal固定百分比而非點數字串。','空進場比':'當日基準×此值/100為向下距離。','最多進場次數':'空手進場每次加一，每日重新畫線時歸零；不是全期總次數。','停損比':'以調整後多／空目標作百分比停損，並非一律實際成交價；每日只重設目標但保留舊停損。','BD線開盤時間':'必須HHmm精確等於才重設或新增，依TimeOfDay回退判第一筆；不作>=補建。','進場調整點':'提早突破並同步平移基準，會令多保護參考價比實際open高此點數、空保護參考比open低此點數。','開始交易時間':'一般報價在此以前標session=1，擋空手入場但有倉停損仍查。','最後交易時間':'一般報價在此以後標session=1，擋空手入場但不強制平倉。'})
add('BD30','每當現行空手基準被突破後補下一條基準，可順勢或逆勢各做一口，以固定停損、直停與追蹤線退出並當沖平倉。','多線突破',['只處理Current近月。在進場時窗內若沒有啟動中空手線且遠離其他啟動基準，就用open新增一條，下一次分派才測上下突破。','突破上目標時順勢多／逆勢空，下目標反向；實際按open成交並平移整組價格，逆勢再交換上下目標，使風控以本次入場價換算。','新進場後同根立即分派持倉保護；可以同時多條有倉線，但最多一條啟動中空手線。'],['先判安全數據錯誤與直接停利；有移停線則只按移停退出，否則按固定停損。其後才依有利價格更新移停線，建立移停時清掉固定停損。','達當沖平倉HHmm後停全部啟動子項，不再建線；固定停損／直停／移停都直接停止該線，不回到空手重進。'],[common,cost,'所有價格判斷與模擬成交按open；%參數以入場目標換算，按最小單位Round。換月偏移基準與各保護價，但主交易迴圈仍硬限Current。'],['進場結束只擋空手進場及建線，既有倉仍管理到當沖截止。共用session=1沒有擋此類空手進場。','session=1會略過直接停利及既有移停分支；已有移停時固定停損已清零，因此時間外可能沒有價格退出。多單尚可在部分路徑新啟移停，空單更新前另有session擋，兩側不對稱。','主迴圈未先檢查啟動才分派所有子項，已停線保留狀態／價位；空手被當沖停用後狀態為停止，不再自然重入。換月後Next也不再被此類處理。'],{'進場比':'新基準上下各距此值，%以建線open換算，純數為點數。','進場方向':'順勢上破多下破空；逆勢上破空下破多，觸發後交換方向目標作風控基準。','停損比':'實際入場目標加減的固定風險距離，%或點數，啟用移停時清零。','直接停利比':'入場目標加減的固定獲利距離，%或點數，並不等到移停啟動才生效。','啟動移停比':'有利走到此距離才建移停；0可在進場同根建立。','移停拉回比':'以入場目標換算固定追蹤距離，再從每筆有利open減／加形成單向線。','進場點數濾網':'建新線時與所有啟動基準的距離若嚴格小於此點數則略過；等於可以建。','進場開始時間':'HHmm，空手突破與新增基準均需>=此時間。','進場結束時間':'HHmm，空手突破與新增基準均需<=此時間；不影響既有倉一般管理。','當沖平倉時間':'HHmm，一般迴圈第一筆>=時全部啟動線按open平倉，無另行末筆補成交。','開始交易時間':'一般報價在此以前標session=1；本版空手不擋，但會影響既有倉的直停與移停。','最後交易時間':'一般報價在此以後標session=1，不直接平倉；既有移停分支會直接略過。'})
add('BD27','每天開盤建一條策略，沿固定格距順勢逐口加碼、逆向逐口減碼；以整組點數目標與當日損失價管理，截止當沖結束。','日內分批加減',['TimeOfDay回退後第一筆>=開始交易時間建空手線，下一筆才測上下格；上破多、下破空各一口，觸價使用進場調整點。','持倉有利走一格，當前絕對口數<最多加碼口數時加一口；不利一格則減一口，只剩一口時退出回空手。每次交易都從當筆open重設上下格。'],['有倉依序判當日損失價、直停價、移停價、兩平價，然後才作格距加減與更新保護。當日損失／直停停止整列，移停／兩平或末口減碼回到空手可再做。','當沖截止或結算把全部策略停止；截止之後當日不再分派，次日重新建線。'],[common,cost,'持倉獲利=部位×open−持倉成本−abs(部位)×滑價，當日獲利再加已實現。點數預算按當時口數折成價格；買賣成本帳也逐側加滑價。','多單移停新線=open−Floor((持倉獲利−移停拉回點數)/口數)，空單反向；這是依內部持倉損益反推價格，不是簡單從最高獲利回吐固定點數。'],['減碼前重算目標時用交易方向選多／空公式及帶符號的預期口數，例如多單減碼會進空側公式並用負數分母；保護價可能失真，不能視為標準加減碼風控。','當日最大損失用該子項自開盤累積獲利，不是全組合每日現金上限；共用session=1沒有擋本版空手進場。','最多加碼口數以decimal門檻比較整數持倉，非整數可加到下一整數。每次Clear未重設私有日界時刻，重跑物件邊界需注意。'],{'加碼進場點數':'每次空手、加碼或減碼後，從實際open上下各設此點數的格距。','最多加碼口數':'限制目前絕對部位，不是加碼次數；初始仍固定一口，門檻為decimal。','直接停利點數':'以本輪持倉獲利反推整組直停價，除計算中的口數，不是每口各賺此值。','啟動移停點數':'本輪持倉獲利門檻，到價才依內部公式計算移停價。','移停拉回點數':'新線以(持倉獲利−此值)/口數反推，而非當前價直接減此值；不同於標準獲利高點回撤幅度。','當日最大損失':'以該子項已實現加持倉損益換算停止價；加減碼時會重算，非全體組合損失停機。','損益兩平出場':'多口或既有兩平線時建立按持倉損益反推的兩平線，到價回空手，仍可再進。','當沖平倉時間':'TimeOfDay回退後第一筆HHmm>=此時間停止全部，當日其後不再管理。','進場調整點':'空手上門檻減此點數／下門檻加此點數，提早建立一口；已有倉加減碼不用。','開始交易時間':'TimeOfDay回退後第一筆>=此值建當日空手線；共用session旗標不擋本版入場。'})
(S/'analysis/SuperChina.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print('Wrote China BD25/27/29/30')
